template<ForwardIterator Iter>
void sort(Iter p, Iter q)
// std::listE 비롯해 순방향 순회만 가능한 타입에 사용
{
vector<Value_type<Iter>> v {p,q};
sort(v);       // 임의 접근 정렬 사용
copy(v.begin(),v.end(),p);
}

